309	/****************************************************************************
310	 * Name: esp_lcd_dpi_panel_init
311	 *
312	 * Description:
313	 *   Start the DPI panel refresh loop.
314	 *   Critical sequence: start DMA → enable video mode → enable DPI output.
315	 ****************************************************************************/
316	
317	int esp_lcd_dpi_panel_init(esp_lcd_dpi_panel_handle_t panel)
318	{
319	  dw_gdma_block_transfer_config_t xfer;
320	  int ret;
321	
322	  if (!panel || !panel->fb)
323	    {
324	      return -EINVAL;
325	    }
326	
327	  /* Create DMA channel (must be done AFTER Camera CSI init which
328	   * resets GDMA and clears all channel configurations).
329	   */
330	
331	  dw_gdma_channel_alloc_config_t dma_cfg;
332	  memset(&dma_cfg, 0, sizeof(dma_cfg));
333	
334	  dma_cfg.src.block_transfer_type      = DW_GDMA_BLOCK_TRANSFER_LIST;
335	  dma_cfg.src.role                     = DW_GDMA_ROLE_MEM;
336	  dma_cfg.src.handshake_type           = DW_GDMA_HANDSHAKE_HW;
337	  dma_cfg.src.num_outstanding_requests = 5;
338	
339	  dma_cfg.dst.block_transfer_type      = DW_GDMA_BLOCK_TRANSFER_LIST;
340	  dma_cfg.dst.role                     = DW_GDMA_ROLE_PERIPH_DSI;
341	  dma_cfg.dst.handshake_type           = DW_GDMA_HANDSHAKE_HW;
342	  dma_cfg.dst.num_outstanding_requests = 2;
343	
344	  dma_cfg.flow_controller              = DW_GDMA_FLOW_CTRL_SELF;
345	  dma_cfg.chan_priority                 = 1;
346	
347	  ret = dw_gdma_new_channel(&dma_cfg, &panel->dma_chan);
348	  if (ret < 0)
349	    {
350	      syslog(LOG_ERR, "[DPI] Failed to create DMA channel: %d\n", ret);
351	      return ret;
352	    }
353	
354	  /* Create DMA link list (1 item, self-cycling) */
355	
356	  dw_gdma_link_list_config_t ll_cfg;
357	  memset(&ll_cfg, 0, sizeof(ll_cfg));
358	  ll_cfg.num_items = 1;
359	
360	  ret = dw_gdma_new_link_list(&ll_cfg, &panel->link_list);
361	  if (ret < 0)
362	    {
363	      syslog(LOG_ERR, "[DPI] Failed to create link list: %d\n", ret);
364	      return ret;
365	    }
366	
367	  /* Register DMA callback — not used with polling approach, skip */
368	
369	  /* Start the refresh polling thread */
370	
371	  panel->refresh_running = true;
372	  kthread_create("dsi_refresh", 200, 2048,
373	                 dsi_dma_refresh_thread, NULL);
374	
375	  /* Configure DMA transfer parameters in the LLI:
376	   *   Source: framebuffer in PSRAM/SRAM (incrementing)
377	   *   Dest:   Bridge FIFO at fixed address
378	   */
379	
380	  memset(&xfer, 0, sizeof(xfer));
381	
382	  xfer.src.addr       = (uint32_t)(uintptr_t)panel->fb;
383	  xfer.src.burst_mode = DW_GDMA_BURST_MODE_INCREMENT;
384	  xfer.src.burst_items = DW_GDMA_BURST_ITEMS_512;
385	  xfer.src.burst_len  = 16;
386	  xfer.src.width      = DW_GDMA_TRANS_WIDTH_64;
387	
388	  xfer.dst.addr       = MIPI_DSI_BRG_MEM_BASE;
389	  xfer.dst.burst_mode = DW_GDMA_BURST_MODE_FIXED;
390	  xfer.dst.burst_items = DW_GDMA_BURST_ITEMS_256;
391	  xfer.dst.burst_len  = 16;
392	  xfer.dst.width      = DW_GDMA_TRANS_WIDTH_64;
393	
394	  /* Size in 64-bit transfer items */
395	
396	  xfer.size = panel->fb_size * 8 / 64;
397	
398	  panel->xfer = xfer;
399	  dw_gdma_lli_config_transfer(
400	      dw_gdma_link_list_get_item(panel->link_list, 0), &panel->xfer);
401	
402	  /* Mark LLI as valid and last. DMA will complete one frame then stop.
403	   * CSI ISR calls esp_dsi_dma_isr_handler() to re-arm for next frame.
404	   */
405	
406	  dw_gdma_block_markers_t markers;
407	  markers.is_valid = true;
408	  markers.is_last  = true;
409	
410	  dw_gdma_lli_set_block_markers(
411	      dw_gdma_link_list_get_item(panel->link_list, 0), markers);
412	
413	  /* Attach link list and start DMA */
414	
415	  dw_gdma_channel_use_link_list(panel->dma_chan, panel->link_list);
416	  dw_gdma_channel_enable_ctrl(panel->dma_chan, true);
417	
418	  /* Enable video mode — THIS triggers the PHY LP→HS transition */
419	
420	  mipi_dsi_host_ll_enable_video_mode(panel->bus->hal.host, true);
421	
422	  /* Enable DPI output on the bridge */
423	
424	  mipi_dsi_brg_ll_enable_dpi_output(panel->bus->hal.bridge, true);
425	  mipi_dsi_brg_ll_update_dpi_config(panel->bus->hal.bridge);
426	
427	  /* Inline re-arm loop: keep DMA running for first 5 seconds
428	   * to verify display works before handing off to refresh thread.
429	   */
430	
431	  {
432	    dw_gdma_dev_t *dev = DW_GDMA_LL_GET_HW(0);
433	    int frames = 0;
434	    for (int i = 0; i < 300; i++)  /* 300 * 16ms = ~5 seconds */
435	      {
436	        usleep(16000);
437	        uint32_t chen = dev->chen0.val;
438	        if (!(chen & (1u << 1)))
439	          {
440	            /* Channel idle — re-arm */
441	
442	            uint32_t st = dw_gdma_ll_channel_get_intr_status(dev, 1);
443	            if (st)
444	              {
445	                dw_gdma_ll_channel_clear_intr(dev, 1, st);
446	              }
447	
448	            dw_gdma_block_markers_t m2;
449	            m2.is_valid = true;
450	            m2.is_last  = true;
451	            dw_gdma_lli_set_block_markers(
452	                dw_gdma_link_list_get_item(panel->link_list, 0), m2);
453	            dw_gdma_channel_use_link_list(panel->dma_chan,
454	                                          panel->link_list);
455	            dw_gdma_channel_enable_ctrl(panel->dma_chan, true);
456	            frames++;
457	          }
458	      }
459	
460	    syslog(LOG_INFO, "[DPI] Inline re-arm: %d frames in 5s\n", frames);
461	  }
462	
463	  syslog(LOG_INFO, "[DPI] Init: DMA started, video mode active\n");
464	  return 0;
465	}
