467	static esp_err_t dpi_panel_draw_bitmap_dma2d_hook(esp_lcd_panel_t *panel, const esp_lcd_draw_bitmap_hook_data_t *hook_data, void* hook_ctx)
468	{
469	    ESP_LOGV(TAG, "copy draw buffer by DMA2D");
470	    esp_lcd_dpi_panel_t *dpi_panel = __containerof(panel, esp_lcd_dpi_panel_t, base);
471	    // ensure the previous draw operation is finished
472	    ESP_RETURN_ON_FALSE(xSemaphoreTake(dpi_panel->draw_sem, 0) == pdTRUE, ESP_ERR_INVALID_STATE,
473	                        TAG, "previous draw operation is not finished");
474	
475	    esp_async_fbcpy_trans_desc_t fbcpy_trans_config = {
476	        .src_buffer = hook_data->src_data,
477	        .dst_buffer = hook_data->dst_data,
478	        .src_buffer_size_x = hook_data->src_x_size,
479	        .src_buffer_size_y = hook_data->src_y_size,
480	        .dst_buffer_size_x = hook_data->dst_x_size,
481	        .dst_buffer_size_y = hook_data->dst_y_size,
482	        .src_offset_x = hook_data->src_x_start,
483	        .src_offset_y = hook_data->src_y_start,
484	        .dst_offset_x = hook_data->dst_x_start,
485	        .dst_offset_y = hook_data->dst_y_start,
486	        .copy_size_x = hook_data->src_x_end - hook_data->src_x_start,
487	        .copy_size_y = hook_data->src_y_end - hook_data->src_y_start,
488	        .pixel_format_fourcc_id = dpi_panel->in_color_format,
489	    };
490	    // save the on_hook_end callback, and invoke it when the async memcpy is done
491	    dpi_panel->on_hook_end = hook_data->on_hook_end;
492	    ESP_RETURN_ON_ERROR(esp_async_fbcpy(dpi_panel->fbcpy_handle, &fbcpy_trans_config, async_fbcpy_done_cb, dpi_panel), TAG, "async memcpy failed");
493	    return ESP_OK;
494	}
