507	esp_err_t esp_lcd_dpi_panel_enable_dma2d(esp_lcd_panel_handle_t panel)
508	{
509	    esp_err_t ret = ESP_OK;
510	    ESP_RETURN_ON_FALSE(panel, ESP_ERR_INVALID_ARG, TAG, "invalid panel");
511	
512	    esp_lcd_dpi_panel_t *dpi_panel = __containerof(panel, esp_lcd_dpi_panel_t, base);
513	
514	    // Check if built-in DMA2D draw bitmap hook is registered
515	    ESP_RETURN_ON_FALSE(!dpi_panel->fbcpy_handle, ESP_ERR_INVALID_STATE, TAG, "draw bitmap DMA2D hook is already registered");
516	
517	    // Initialize DMA2D resources
518	    esp_async_fbcpy_config_t fbcpy_config = {};
519	    ESP_RETURN_ON_ERROR(esp_async_fbcpy_install(&fbcpy_config, &dpi_panel->fbcpy_handle), TAG, "install async memcpy 2d failed");
520	
521	    dpi_panel->draw_sem = xSemaphoreCreateBinaryWithCaps(DSI_MEM_ALLOC_CAPS);
522	    ESP_GOTO_ON_FALSE(dpi_panel->draw_sem, ESP_ERR_NO_MEM, err, TAG, "no memory for draw semaphore");
523	    xSemaphoreGive(dpi_panel->draw_sem);
524	    // Register the DMA2D draw bitmap hook
525	    esp_lcd_panel_hooks_t hooks = {
526	        .draw_bitmap_hook = dpi_panel_draw_bitmap_dma2d_hook,
527	    };
528	    ESP_GOTO_ON_ERROR(esp_lcd_dpi_panel_register_hooks(panel, &hooks, dpi_panel->user_ctx), err, TAG, "register DMA2D draw bitmap hook failed");
529	
530	    return ESP_OK;
531	
532	err:
533	    if (dpi_panel->fbcpy_handle) {
534	        esp_async_fbcpy_uninstall(dpi_panel->fbcpy_handle);
535	        dpi_panel->fbcpy_handle = NULL;
536	    }
537	    if (dpi_panel->draw_sem) {
538	        vSemaphoreDeleteWithCaps(dpi_panel->draw_sem);
539	        dpi_panel->draw_sem = NULL;
540	    }
541	    return ret;
542	}
