914	/****************************************************************************
915	 * Name: esp_mipi_dsi_flush_fb
916	 *
917	 * Description:
918	 *   Flush the framebuffer content to the DSI bridge FIFO. Must be called
919	 *   after the framebuffer is updated (e.g., after each camera frame is
920	 *   rendered). In video mode, the bridge continuously reads from its FIFO
921	 *   and sends to the panel via DPI. This CPU copy feeds the FIFO.
922	 *
923	 ****************************************************************************/
924	
925	void esp_mipi_dsi_flush_fb(void)
926	{
927	  volatile uint32_t *brg_mem = (volatile uint32_t *)MIPI_DSI_BRG_MEM_BASE;
928	  uint32_t *fb32 = (uint32_t *)g_framebuffer;
929	  uint32_t words;
930	  uint32_t i;
931	
932	  if (g_framebuffer == NULL)
933	    {
934	      return;
935	    }
936	
937	  words = ESP_DSI_FB_SIZE / 4;
938	  for (i = 0; i < words; i++)
939	    {
940	      brg_mem[0] = fb32[i];
941	    }
942	}
943	
944	/****************************************************************************
945	 * Name: esp_mipi_dsi_start_refresh
946	 *
947	 * Description:
948	 *   Start continuous DW-GDMA transfer from framebuffer to DSI bridge FIFO
949	 *   using a self-looping link list (LLI whose next pointer points to
950	 *   itself). This provides infinite hardware-driven refresh without ISR.
951	 *
952	 *   Mirrors ESP-IDF esp_lcd_panel_dpi.c: MEM→PERIPH_DSI, flow=SELF,
953	 *   HW handshake, LIST block transfer mode.
954	 *
955	 *   MUST be called after DW-GDMA controller is enabled (camera init).
956	 ****************************************************************************/
957	
958	/****************************************************************************
959	 * Name: dsi_dma_init_lli
960	 *
961	 * Description:
962	 *   Initialize the self-cycling DMA Link List Item (LLI) for DSI refresh.
963	 *   The LLI's next pointer points to itself → infinite hardware cycling.
964	 ****************************************************************************/
965	
966	static void dsi_dma_init_lli(void)
967	{
968	  dw_gdma_link_list_item_t *lli_cached =
969	      (dw_gdma_link_list_item_t *)g_dsi_lli_mem;
970	  g_dsi_lli_nc = (dw_gdma_link_list_item_t *)
971	      ((uintptr_t)lli_cached + SOC_NON_CACHEABLE_OFFSET_SRAM);
972	
973	  /* Flush+invalidate the LLI memory so non-cached alias sees zeros */
974	
975	  esp_cache_msync(lli_cached, sizeof(g_dsi_lli_mem),
976	                  ESP_CACHE_MSYNC_FLAG_DIR_C2M |
977	                  ESP_CACHE_MSYNC_FLAG_INVALIDATE);
978	
979	  /* Configure LLI transfer: framebuffer → bridge FIFO */
980	
981	  dw_gdma_ll_lli_set_src_addr(g_dsi_lli_nc,
982	                              (uint32_t)(uintptr_t)g_framebuffer);
983	  dw_gdma_ll_lli_set_dst_addr(g_dsi_lli_nc, MIPI_DSI_BRG_MEM_BASE);
984	  dw_gdma_ll_lli_set_trans_block_size(g_dsi_lli_nc,
985	                                      ESP_DSI_FB_SIZE / 8);
986	
987	  /* Source: PSRAM framebuffer, incrementing, 64-bit, burst 512×16 */
988	
989	  dw_gdma_ll_lli_set_src_master_port(g_dsi_lli_nc,
990	                                     (uintptr_t)g_framebuffer);
991	  dw_gdma_ll_lli_set_src_burst_mode(g_dsi_lli_nc,
992	                                    DW_GDMA_BURST_MODE_INCREMENT);
993	  dw_gdma_ll_lli_set_src_trans_width(g_dsi_lli_nc,
994	                                     DW_GDMA_TRANS_WIDTH_64);
995	  dw_gdma_ll_lli_set_src_burst_items(g_dsi_lli_nc,
996	                                     DW_GDMA_BURST_ITEMS_512);
997	  dw_gdma_ll_lli_set_src_burst_len(g_dsi_lli_nc, 16);
998	
999	  /* Destination: bridge FIFO, fixed address, 64-bit, burst 256×16 */
1000	
1001	  dw_gdma_ll_lli_set_dst_master_port(g_dsi_lli_nc,
1002	                                     MIPI_DSI_BRG_MEM_BASE);
1003	  dw_gdma_ll_lli_set_dst_burst_mode(g_dsi_lli_nc,
1004	                                    DW_GDMA_BURST_MODE_FIXED);
1005	  dw_gdma_ll_lli_set_dst_trans_width(g_dsi_lli_nc,
1006	                                     DW_GDMA_TRANS_WIDTH_64);
1007	  dw_gdma_ll_lli_set_dst_burst_items(g_dsi_lli_nc,
1008	                                     DW_GDMA_BURST_ITEMS_256);
1009	  dw_gdma_ll_lli_set_dst_burst_len(g_dsi_lli_nc, 16);
1010	
1011	  /* Self-cycling: next pointer = this LLI (cached address for HW) */
1012	
1013	  dw_gdma_ll_lli_set_next_item_addr(g_dsi_lli_nc,
1014	                                    (uint32_t)(uintptr_t)lli_cached);
1015	  dw_gdma_ll_lli_set_link_list_master_port(g_dsi_lli_nc,
1016	                                           DW_GDMA_LL_MASTER_PORT_MEMORY);
1017	
1018	  /* Block markers: valid=1, last=1, intr on done=1 */
1019	
1020	  dw_gdma_ll_lli_set_block_markers(g_dsi_lli_nc, true, true, true);
1021	}
1022	
1023	/****************************************************************************
1024	 * Name: dsi_dma_start_linked_list
1025	 *
1026	 * Description:
1027	 *   Configure DMA channel 1 for linked-list mode and start it.
1028	 *   The channel will continuously cycle through the single self-pointing
1029	 *   LLI, pushing framebuffer data to the bridge without CPU intervention.
1030	 ****************************************************************************/
1031	
1032	static void dsi_dma_start_linked_list(void)
1033	{
1034	  dw_gdma_dev_t *dev = DW_GDMA_LL_GET_HW(0);
1035	  const uint8_t ch = 1;
1036	
1037	  /* Declare RCC atomic env variable required by LL macros */
1038	
1039	  int __DECLARE_RCC_ATOMIC_ENV;
1040	  (void)__DECLARE_RCC_ATOMIC_ENV;
1041	
1042	  /* Initialize DW-GDMA controller (bus clock, reset, enable).
1043	   * This is idempotent — safe to call even if camera already did it.
1044	   */
1045	
1046	  dw_gdma_ll_enable_bus_clock(0, true);
1047	  dw_gdma_ll_reset_register(0);
1048	  dw_gdma_ll_reset(dev);
1049	  dw_gdma_ll_enable_controller(dev, true);
1050	  dw_gdma_ll_enable_intr_global(dev, true);
1051	
1052	  /* Linked-list mode for both src and dst */
1053	
1054	  dw_gdma_ll_channel_set_src_multi_block_type(dev, ch,
1055	                                     DW_GDMA_BLOCK_TRANSFER_LIST);
1056	  dw_gdma_ll_channel_set_dst_multi_block_type(dev, ch,
1057	                                     DW_GDMA_BLOCK_TRANSFER_LIST);
1058	
1059	  /* Flow: MEM → PERIPH_DSI, DMA is flow controller */
1060	
1061	  dw_gdma_ll_channel_set_trans_flow(dev, ch,
1062	                                    DW_GDMA_ROLE_MEM,
1063	                                    DW_GDMA_ROLE_PERIPH_DSI,
1064	                                    DW_GDMA_FLOW_CTRL_SELF);
1065	
1066	  /* Hardware handshake for DSI bridge */
1067	
1068	  dw_gdma_ll_channel_set_src_handshake_interface(dev, ch,
1069	                                                 DW_GDMA_HANDSHAKE_HW);
1070	  dw_gdma_ll_channel_set_dst_handshake_interface(dev, ch,
1071	                                                 DW_GDMA_HANDSHAKE_HW);
1072	  dw_gdma_ll_channel_set_dst_handshake_periph(dev, ch,
1073	                                              DW_GDMA_ROLE_PERIPH_DSI);
1074	
1075	  /* Outstanding requests (match ESP-IDF golden: src=5, dst=2) */
1076	
1077	  dw_gdma_ll_channel_set_src_outstanding_limit(dev, ch, 5);
1078	  dw_gdma_ll_channel_set_dst_outstanding_limit(dev, ch, 2);
1079	  dw_gdma_ll_channel_set_priority(dev, ch, 1);
1080	
1081	  /* Point channel at our LLI (cached address — HW fetches via cache) */
1082	
1083	  dw_gdma_ll_channel_set_link_list_master_port(dev, ch,
1084	                                               DW_GDMA_LL_MASTER_PORT_MEMORY);
1085	  dw_gdma_ll_channel_set_link_list_head_addr(dev, ch,
1086	      (uint32_t)(uintptr_t)g_dsi_lli_mem);
1087	
1088	  /* Enable DMA_TFR_DONE interrupt for ch1 so the shared ISR can re-arm.
1089	   * Only TFR_DONE — do not propagate other events to avoid storm.
1090	   */
1091	
1092	  dw_gdma_ll_channel_clear_intr(dev, ch, UINT32_MAX);
1093	  dw_gdma_ll_channel_enable_intr_generation(dev, ch, UINT32_MAX, false);
1094	  dw_gdma_ll_channel_enable_intr_propagation(dev, ch, UINT32_MAX, false);
1095	
1096	  /* Now selectively enable only DMA_TFR_DONE */
1097	
1098	  dw_gdma_ll_channel_enable_intr_generation(dev, ch,
1099	                         DW_GDMA_LL_CHANNEL_EVENT_DMA_TFR_DONE, true);
1100	  dw_gdma_ll_channel_enable_intr_propagation(dev, ch,
1101	                         DW_GDMA_LL_CHANNEL_EVENT_DMA_TFR_DONE, true);
1102	
1103	  /* Enable the channel — DMA starts immediately */
1104	
1105	  dw_gdma_ll_channel_enable(dev, ch, true);
1106	}
1107	
1108	/****************************************************************************
1109	 * Name: esp_dsi_dma_isr_handler
1110	 *
1111	 * Description:
1112	 *   Called from the shared DW-GDMA ISR when channel 1 fires DMA_TFR_DONE.
1113	 *   Re-points LLP at our self-cycling LLI and re-enables the channel.
1114	 ****************************************************************************/
1115	
1116	void esp_dsi_dma_isr_handler(void)
1117	{
1118	  dw_gdma_dev_t *dev = DW_GDMA_LL_GET_HW(0);
1119	  const uint8_t ch = 1;
1120	
1121	  /* Clear all ch1 interrupts */
1122	
1123	  dw_gdma_ll_channel_clear_intr(dev, ch, UINT32_MAX);
1124	
1125	  /* Re-point LLP and re-enable channel */
1126	
1127	  dw_gdma_ll_channel_set_link_list_head_addr(dev, ch,
1128	      (uint32_t)(uintptr_t)g_dsi_lli_mem);
1129	  dw_gdma_ll_channel_enable(dev, ch, true);
1130	}
1131	
1132	void esp_mipi_dsi_start_refresh(void)
1133	{
1134	  if (g_framebuffer == NULL)
1135	    {
1136	      return;
1137	    }
1138	
1139	  /* Write back framebuffer to physical PSRAM for DMA access.
1140	   * On ESP32-P4, PSRAM at 0x48xxxxxx has non-cached alias at 0x88xxxxxx.
1141	   * Belt-and-suspenders: do cache writeback AND write through non-cached.
1142	   */
1143	
1144	  esp_cache_msync((void *)g_framebuffer, ESP_DSI_FB_SIZE,
1145	                  ESP_CACHE_MSYNC_FLAG_DIR_C2M);
1146	
1147	  /* Also fill via non-cached alias to guarantee physical write */
1148	  {
1149	    volatile uint8_t *fb_nc = (volatile uint8_t *)
1150	        ((uintptr_t)g_framebuffer + 0x40000000);
1151	    uint32_t j;
1152	    for (j = 0; j < ESP_DSI_FB_SIZE; j += 3)
1153	      {
1154	        fb_nc[j + 0] = 0xff;  /* R */
1155	        fb_nc[j + 1] = 0x00;  /* G */
1156	        fb_nc[j + 2] = 0x00;  /* B */
1157	      }
1158	  }
1159	
1160	  /* Initialize the self-cycling LLI descriptor */
1161	
1162	  dsi_dma_init_lli();
1163	
1164	  /* Enable the bridge (must happen after panel DCS init, before DMA) */
1165	
1166	  syslog(LOG_INFO, "[DSI] Enabling bridge...\n");
1167	  mipi_dsi_brg_ll_enable(g_dsi_hal.bridge, true);
1168	  mipi_dsi_brg_ll_update_dpi_config(g_dsi_hal.bridge);
1169	
1170	  /* Start linked-list DMA — begins pushing FB to bridge FIFO */
1171	
1172	  syslog(LOG_INFO, "[DSI] Starting DMA linked-list...\n");
1173	  dsi_dma_start_linked_list();
1174	
1175	  /* NOW enable video mode + DPI output (bridge has data to send) */
1176	
1177	  syslog(LOG_INFO, "[DSI] Enabling video mode + DPI output...\n");
1178	  mipi_dsi_host_ll_enable_video_mode(g_dsi_hal.host, true);
1179	  mipi_dsi_brg_ll_enable_dpi_output(g_dsi_hal.bridge, true);
1180	  mipi_dsi_brg_ll_update_dpi_config(g_dsi_hal.bridge);
1181	
1182	  syslog(LOG_INFO, "[DSI] Linked-list DMA refresh started\n");
1183	}
1184

