                                  const dw_gdma_trans_done_event_data_t *event_data,
                                  void *user_data)
{
  struct esp_lcd_dpi_panel_t *panel = user_data;
  dw_gdma_link_list_item_t *lli;
  dw_gdma_block_markers_t m;

  (void)event_data;

  if (!panel)
    {
      return false;
    }

  lli = dw_gdma_link_list_get_item(panel->link_list, 0);
  dw_gdma_lli_config_transfer(lli, &panel->xfer);
  m.is_valid = true;
  m.is_last  = true;
  dw_gdma_lli_set_block_markers(lli, m);
  dw_gdma_channel_use_link_list(chan, panel->link_list);
  dw_gdma_channel_enable_ctrl(chan, true);
  return false;
}

